// tracker-state.js: domain, no DOM.
export const initial = { status: "idle", items: [], error: null };

export function reduce(state, event) {
  switch (event.type) {
    case "load":    return { ...state, status: "loading", error: null };
    case "loaded":  return { status: event.items.length ? "ready" : "empty", items: event.items, error: null };
    case "failed":  return { ...state, status: "error", error: event.message };
    default:        return state;
  }
}

// tracker-view.js: renders every status, text only via textContent.
export function render(root, state) {
  root.setAttribute("aria-busy", String(state.status === "loading"));
  const message = {
    loading: "Loading your subjects...",
    empty: "No subjects yet. Add your first one above.",
    error: `Couldn't load subjects. ${state.error ?? ""}`,
  }[state.status];
  root.querySelector("[data-status]").textContent = message ?? "";
  root.querySelector("[data-retry]").hidden = state.status !== "error";
  // ready: rebuild the list with createElement + textContent.
}
```

| State | What the learner gets |
|---|---|
| loading. | message plus aria-busy. |
| empty. | a prompt to add a subject. |
| ready. | the list, keyboard-reachable. |
| validation error. | field message, aria-invalid, focus. |
| server error. | message plus a Retry button. |
| stale request. | aborted, never shown. |

